def split_csv(line):
    if line == "":
        return [""]

    fields = []
    i = 0

    while i < len(line):
        if line[i] == '"':
            # Quoted field
            i += 1
            field = ""
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what comes next
                        if i < len(line):
                            if line[i] == ',':
                                i += 1
                            else:
                                # Invalid: closing quote not followed by comma or end of line
                                return None
                        fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # End of line reached without finding closing quote
                return None
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Invalid: unquoted field contains double quote
                    return None
                field += line[i]
                i += 1

            fields.append(field)

            if i < len(line):
                # Skip the comma
                i += 1

    return fields

